META = dict(
    n=10, featured=[20, 41], name='Divine Glories', skt_name='विभूतियोगः', roman_name='Vibhuti Yoga',
    outline="Verses 1–7: Krishna is the unborn source of the gods, the sages and every quality found in beings; 8–11: how the wise worship him, and what he gives them; 12–18: Arjuna accepts this and asks to hear his glories; 19–38: “Among these, I am this”, the best of every kind; 39–42: nothing exists without him, and all of it is one small part of him.",
)
V = {
1: ("""भूयः एव = once again | महा-बाहो = O mighty-armed (Arjuna) | शृणु मे परमं वचः = hear my highest word | यत् ते अहं वक्ष्यामि = which I shall tell you | प्रीयमाणाय = who take delight in it | हित-काम्यया = wishing your good""",
    "Krishna said: Arjuna, listen once more to my highest teaching. I shall tell it to you because you delight in it and because I wish you well."),
2: ("""न मे विदुः प्रभवम् = do not know my origin | सुर-गणाः = the hosts of gods | न महर्षयः = nor the great sages | अहम् आदिः हि = for I am the source | देवानां महर्षीणां च = of the gods and the great sages | सर्वशः = in every way""",
    "Neither the hosts of gods nor the great sages know my origin, for I am the source of the gods and the great sages in every way."),
3: ("""यः मां वेत्ति = whoever knows me | अजम् अनादिं च = as unborn and without beginning | लोक-महेश्वरम् = the great Lord of the worlds | असम्मूढः सः मर्त्येषु = that person, undeluded among mortals | सर्व-पापैः प्रमुच्यते = is freed from all wrongs""",
    "Whoever knows me as unborn and without beginning, the great Lord of the worlds, is undeluded among mortals and is freed from all wrongs."),
4: ("""बुद्धिः ज्ञानम् = intelligence, knowledge | असंमोहः = freedom from delusion | क्षमा सत्यम् = forgiveness, truthfulness | दमः शमः = self-control, calmness | सुखं दुःखम् = pleasure, pain | भवः अभावः = birth, death | भयं च अभयम् एव च = fear and also fearlessness""",
    "Intelligence, knowledge, freedom from delusion, forgiveness, truthfulness, self-control and calmness; pleasure and pain, birth and death, fear and fearlessness;"),
5: ("""अहिंसा समता तुष्टिः = non-violence, even-mindedness, contentment | तपः दानम् = discipline, giving | यशः अयशः = fame, ill fame | भवन्ति भावाः भूतानाम् = these states of beings arise | मत्तः एव = from me alone | पृथक्-विधाः = in their different kinds""",
    "non-violence, even-mindedness, contentment, self-discipline, giving, fame and ill fame: all these different states of beings come from me alone."),
6: ("""महर्षयः सप्त = the seven great sages | पूर्वे चत्वारः = the four before them | मनवः तथा = and also the Manus | मत्-भावाः = have my nature | मानसाः जाताः = born from my mind | येषां लोके इमाः प्रजाः = from whom all the people in the world have come""",
    "The seven great sages, the four who came before them, and the Manus all have my nature and were born from my mind. From them have come all the people of the world."),
7: ("""एतां विभूतिं योगं च मम = this glory and power of mine | यः वेत्ति तत्त्वतः = whoever truly knows | सः अविकम्पेन योगेन युज्यते = is united with me in unshakeable yoga | न अत्र संशयः = there is no doubt of this""",
    "Whoever truly knows this glory and power of mine is united with me in a yoga that cannot be shaken. There is no doubt of this."),
8: ("""अहं सर्वस्य प्रभवः = I am the source of all | मत्तः सर्वं प्रवर्तते = everything proceeds from me | इति मत्वा = knowing this | भजन्ते मां बुधाः = the wise worship me | भाव-समन्विताः = with all their heart""",
    "I am the source of all, and everything proceeds from me. Knowing this, the wise worship me with all their heart."),
9: ("""मत्-चित्ताः = with their minds on me | मत्-गत-प्राणाः = with their lives given to me | बोधयन्तः परस्परम् = teaching one another | कथयन्तः च मां नित्यम् = and always speaking of me | तुष्यन्ति च रमन्ति च = they are content and full of joy""",
    "With their minds on me and their lives given to me, teaching one another and always speaking of me, they are content and full of joy."),
10: ("""तेषां सतत-युक्तानाम् = to those who are always united with me | भजतां प्रीति-पूर्वकम् = who worship me with love | ददामि बुद्धि-योगं तम् = I give that yoga of understanding | येन माम् उपयान्ति ते = by which they come to me""",
    "To those who are always united with me and worship me with love, I give the understanding by which they come to me."),
11: ("""तेषाम् एव अनुकम्पा-अर्थम् = out of compassion for them | अहं नाशयामि = I destroy | अज्ञान-जं तमः = the darkness born of ignorance | आत्म-भाव-स्थः = living in their hearts | ज्ञान-दीपेन भास्वता = with the shining lamp of knowledge""",
    "Out of compassion for them, I live in their hearts and destroy the darkness born of ignorance with the shining lamp of knowledge."),
12: ("""परं ब्रह्म = the supreme Brahman | परं धाम = the supreme home | पवित्रं परमं भवान् = you are the supreme purifier | पुरुषं शाश्वतं दिव्यम् = the eternal, divine Person | आदि-देवम् = the first of the gods | अजं विभुम् = unborn and present everywhere""",
    "Arjuna said: You are the supreme Brahman, the supreme home and the supreme purifier. The eternal divine Person, the first of the gods, unborn and present everywhere:"),
13: ("""आहुः त्वाम् ऋषयः सर्वे = so all the sages call you | देवर्षिः नारदः तथा = and the divine sage Narada | असितः देवलः व्यासः = Asita, Devala and Vyasa | स्वयं च एव ब्रवीषि मे = and you yourself tell me so""",
    "this is what all the sages call you, and the divine sage Narada, and Asita, Devala and Vyasa. And now you yourself tell me so."),
14: ("""सर्वम् एतत् ऋतं मन्ये = I hold all this to be true | यत् मां वदसि = that you tell me | केशव = O Keshava (Krishna) | न हि ते भगवन् व्यक्तिं विदुः = for, Lord, they do not know your true form | देवाः न दानवाः = neither the gods nor the demons""",
    "I hold all that you tell me to be true, Krishna. Neither the gods nor the demons, Lord, know your true form."),
15: ("""स्वयम् एव आत्मना आत्मानं वेत्थ त्वम् = you alone know yourself by yourself | पुरुषोत्तम = O Supreme Person | भूत-भावन = source of beings | भूत-ईश = Lord of beings | देव-देव = God of gods | जगत्-पते = Lord of the world""",
    "You alone know yourself by yourself, O Supreme Person, source of all beings, Lord of beings, God of gods, Lord of the world."),
16: ("""वक्तुम् अर्हसि अशेषेण = please tell, leaving nothing out | दिव्याः हि आत्म-विभूतयः = your own divine glories | याभिः विभूतिभिः = the glories by which | लोकान् इमान् त्वं व्याप्य तिष्ठसि = you fill these worlds and remain in them""",
    "Please tell me in full of your divine glories, the glories by which you fill these worlds and live in them."),
17: ("""कथं विद्याम् अहम् = how may I know | योगिन् = O master of yoga | त्वां सदा परिचिन्तयन् = you, by always thinking of you | केषु केषु च भावेषु = and in which forms | चिन्त्यः असि = are you to be thought of | भगवन् मया = by me, Lord""",
    "Master of yoga, how may I come to know you by always thinking of you? In which forms, Lord, should I think of you?"),
18: ("""विस्तरेण = in detail | आत्मनः योगं विभूतिं च = your power and your glory | जनार्दन = O Janardana (Krishna) | भूयः कथय = tell again | तृप्तिः हि न अस्ति मे = for I never have enough | शृण्वतः अमृतम् = of hearing this nectar""",
    "Tell me again, Krishna, in detail, of your power and your glory. I can never hear enough of your words, which are like nectar."),
19: ("""हन्त ते कथयिष्यामि = very well, I shall tell you | दिव्याः हि आत्म-विभूतयः = my own divine glories | प्राधान्यतः = the chief ones only | कुरु-श्रेष्ठ = O best of the Kurus (Arjuna) | न अस्ति अन्तः विस्तरस्य मे = for there is no end to my extent""",
    "Krishna said: Very well. I shall tell you of my divine glories, Arjuna, but only the chief ones, for there is no end to them."),
20: ("""अहम् आत्मा = I am the Self | गुडाकेश = O conqueror of sleep (Arjuna) | सर्व-भूत-आशय-स्थितः = seated in the heart of all beings | अहम् आदिः च मध्यं च = I am the beginning and the middle | भूतानाम् अन्तः एव च = and also the end of beings""",
    "Arjuna, I am the Self seated in the heart of all beings. I am the beginning, the middle and the end of all beings."),
21: ("""आदित्यानाम् अहं विष्णुः = among the Adityas I am Vishnu | ज्योतिषां रविः अंशुमान् = among lights, the radiant sun | मरीचिः मरुताम् अस्मि = among the Maruts (storm gods) I am Marichi | नक्षत्राणाम् अहं शशी = among the stars I am the moon""",
    "Among the Adityas I am Vishnu; among lights, the radiant sun. Among the storm gods I am Marichi; among the stars of the night, I am the moon."),
22: ("""वेदानां सामवेदः अस्मि = of the Vedas I am the Sama Veda | देवानाम् अस्मि वासवः = of the gods I am Indra | इन्द्रियाणां मनः च अस्मि = of the senses I am the mind | भूतानाम् अस्मि चेतना = in living beings I am consciousness""",
    "Of the Vedas I am the Sama Veda; of the gods I am Indra. Of the senses I am the mind; in living beings I am consciousness."),
23: ("""रुद्राणां शङ्करः च अस्मि = of the Rudras I am Shankara (Shiva) | वित्त-ईशः यक्ष-रक्षसाम् = of the yakshas and rakshasas, Kubera, lord of wealth | वसूनां पावकः च अस्मि = of the Vasus I am fire | मेरुः शिखरिणाम् अहम् = of mountain peaks I am Meru""",
    "Of the Rudras I am Shiva; of the yakshas and rakshasas I am Kubera, lord of wealth. Of the Vasus I am fire; of mountain peaks I am Meru."),
24: ("""पुरोधसां च मुख्यं मां विद्धि = know me as the chief of priests | पार्थ = O Partha (Arjuna) | बृहस्पतिम् = Brihaspati | सेनानीनाम् अहं स्कन्दः = of army commanders I am Skanda (Kartikeya) | सरसाम् अस्मि सागरः = of waters I am the ocean""",
    "Know me, Arjuna, as Brihaspati, the chief of priests. Of army commanders I am Skanda; of all waters I am the ocean."),
25: ("""महर्षीणां भृगुः अहम् = of the great sages I am Bhrigu | गिराम् अस्मि एकम् अक्षरम् = of words I am the one syllable (Om) | यज्ञानां जप-यज्ञः अस्मि = of sacrifices I am japa, the quiet repetition of the holy name | स्थावराणां हिमालयः = of things that do not move, the Himalaya""",
    "Of the great sages I am Bhrigu; of words I am the one syllable Om. Of sacrifices I am japa, the quiet repetition of the holy name; of things that do not move, I am the Himalaya."),
26: ("""अश्वत्थः सर्व-वृक्षाणाम् = of all trees, the sacred fig (peepal) | देवर्षीणां च नारदः = of the divine sages, Narada | गन्धर्वाणां चित्ररथः = of the gandharvas (heavenly musicians), Chitraratha | सिद्धानां कपिलः मुनिः = of the perfected, the sage Kapila""",
    "Of all trees I am the peepal; of the divine sages, Narada. Of the heavenly musicians I am Chitraratha; of the perfected ones, the sage Kapila."),
27: ("""उच्चैःश्रवसम् अश्वानाम् = of horses, Ucchaihshravas | विद्धि माम् = know me to be | अमृत-उद्भवम् = born from the nectar | ऐरावतं गज-इन्द्राणाम् = of lordly elephants, Airavata | नराणां च नर-अधिपम् = and of people, the king""",
    "Of horses, know me to be Ucchaihshravas, who rose from the churning for nectar. Of lordly elephants I am Airavata, and among people I am the king."),
28: ("""आयुधानाम् अहं वज्रम् = of weapons I am the thunderbolt | धेनूनाम् अस्मि कामधुक् = of cows I am Kamadhenu, who grants wishes | प्रजनः च अस्मि कन्दर्पः = I am Kandarpa, the god of love, the cause of birth | सर्पाणाम् अस्मि वासुकिः = of serpents I am Vasuki""",
    "Of weapons I am the thunderbolt; of cows I am Kamadhenu, who grants every wish. I am Kandarpa, the god of love, through whom children are born; of serpents I am Vasuki."),
29: ("""अनन्तः च अस्मि नागानाम् = of the nagas I am Ananta | वरुणः यादसाम् अहम् = of water beings I am Varuna | पितॄणाम् अर्यमा च अस्मि = of the ancestors I am Aryama | यमः संयमताम् अहम् = of those who keep order I am Yama""",
    "Of the nagas I am Ananta; of the beings of the water I am Varuna. Of the ancestors I am Aryama; of those who keep order I am Yama."),
30: ("""प्रह्लादः च अस्मि दैत्यानाम् = of the daityas I am Prahlada | कालः कलयताम् अहम् = of those who measure I am time | मृगाणां च मृग-इन्द्रः अहम् = of animals I am the lion, their king | वैनतेयः च पक्षिणाम् = and of birds, Garuda, son of Vinata""",
    "Of the daityas I am Prahlada; of all that measures, I am time. Of animals I am the lion, and of birds I am Garuda."),
31: ("""पवनः पवताम् अस्मि = of purifiers I am the wind | रामः शस्त्र-भृताम् अहम् = of those who bear weapons I am Rama | झषाणां मकरः च अस्मि = of fishes I am the makara, the great sea creature | स्रोतसाम् अस्मि जाह्नवी = of rivers I am the Ganga""",
    "Of purifiers I am the wind; of those who bear weapons I am Rama. Of the creatures of the water I am the makara; of rivers I am the Ganga."),
32: ("""सर्गाणाम् आदिः अन्तः च = of creations I am the beginning and the end | मध्यं च एव अहम् = and also the middle | अर्जुन = O Arjuna | अध्यात्म-विद्या विद्यानाम् = of all knowledge, the knowledge of the Self | वादः प्रवदताम् अहम् = of those who debate, I am honest reasoning""",
    "Of all creations I am the beginning, the middle and the end, Arjuna. Of all kinds of knowledge I am the knowledge of the Self; among those who debate, I am the reasoning that seeks the truth."),
33: ("""अक्षराणाम् अकारः अस्मि = of letters I am the letter A | द्वन्द्वः सामासिकस्य च = of compound words, the pair (dvandva) | अहम् एव अक्षयः कालः = I am time that never ends | धाता अहं विश्वतः-मुखः = I am the supporter who faces every way""",
    "Of letters I am the letter A; of compound words I am the pair, in which both words are equal. I am time that never ends, and I am the supporter whose face is turned in every direction."),
34: ("""मृत्युः सर्व-हरः च अहम् = I am death, which carries off everything | उद्भवः च भविष्यताम् = and the origin of all that is yet to be | कीर्तिः श्रीः वाक् च नारीणाम् = of the feminine, fame, fortune and speech | स्मृतिः मेधा धृतिः क्षमा = memory, intelligence, steadiness and forgiveness""",
    "I am death, which carries off everything, and I am the origin of all that is yet to be. Of the feminine I am fame, fortune, speech, memory, intelligence, steadiness and forgiveness."),
35: ("""बृहत्-साम तथा साम्नाम् = of the Sama hymns, the Brihat Saman | गायत्री छन्दसाम् अहम् = of metres I am the Gayatri | मासानां मार्गशीर्षः अहम् = of months I am Margashirsha (November–December) | ऋतूनां कुसुमाकरः = of seasons, spring, the time of flowers""",
    "Of the Sama hymns I am the Brihat Saman; of poetic metres I am the Gayatri. Of months I am Margashirsha; of seasons I am spring, the time of flowers."),
36: ("""द्यूतं छलयताम् अस्मि = of those who cheat I am gambling | तेजः तेजस्विनाम् अहम् = I am the brilliance of the brilliant | जयः अस्मि = I am victory | व्यवसायः अस्मि = I am resolve | सत्त्वं सत्त्ववताम् अहम् = I am the goodness of the good""",
    "Of those who cheat I am the gambling; of the brilliant I am the brilliance. I am victory, I am resolve, and I am the goodness of the good."),
37: ("""वृष्णीनां वासुदेवः अस्मि = of the Vrishnis I am Vasudeva (Krishna) | पाण्डवानां धनञ्जयः = of the Pandavas, Dhananjaya (Arjuna) | मुनीनाम् अपि अहं व्यासः = of the sages I am Vyasa | कवीनाम् उशना कविः = of poets, the poet Ushana (Shukracharya)""",
    "Of the Vrishnis I am Krishna; of the Pandavas I am Arjuna. Of the sages I am Vyasa; of poets I am the poet Ushana."),
38: ("""दण्डः दमयताम् अस्मि = of those who discipline I am the rod of punishment | नीतिः अस्मि जिगीषताम् = of those who seek victory I am right conduct | मौनं च एव अस्मि गुह्यानाम् = of secrets I am silence | ज्ञानं ज्ञानवताम् अहम् = I am the knowledge of those who know""",
    "Of those who discipline I am the rod; of those who seek victory I am right conduct. Of secrets I am silence, and I am the knowledge of those who know."),
39: ("""यत् च अपि सर्व-भूतानां बीजम् = and whatever is the seed of all beings | तत् अहम् = that I am | अर्जुन = O Arjuna | न तत् अस्ति = there is nothing | भूतं चर-अचरम् = no being, moving or unmoving | विना यत् स्यात् मया = that could exist without me""",
    "And I am the seed of all beings, Arjuna. Nothing that moves or does not move could exist without me."),
40: ("""न अन्तः अस्ति = there is no end | मम दिव्यानां विभूतीनाम् = to my divine glories | परन्तप = O scorcher of foes (Arjuna) | एषः तु उद्देशतः प्रोक्तः = this has been told only as a sample | विभूतेः विस्तरः मया = of the extent of my glory, by me""",
    "There is no end to my divine glories, Arjuna. What I have told you is only a sample of how far they reach."),
41: ("""यत् यत् विभूतिमत् सत्त्वम् = whatever being has glory | श्रीमत् ऊर्जितम् एव वा = or beauty or strength | तत् तत् एव अवगच्छ त्वम् = know that every one of them | मम तेजः-अंश-सम्भवम् = has come from a spark of my splendour""",
    "Whatever has glory, beauty or strength, know that it has come from a spark of my splendour."),
42: ("""अथवा = but then | बहुना एतेन किं ज्ञातेन तव = what use is it for you to know all this detail | अर्जुन = O Arjuna | विष्टभ्य अहम् इदं कृत्स्नं जगत् = I hold up this whole world | एक-अंशेन स्थितः = and stand, with one small part of myself""",
    "But what need is there for you to know all this, Arjuna? I hold up this whole world with only one small part of myself."),
}
